// Compute checksums for entities from system A and system B.
// In production these are read from each source system (ingestion DB, provider feed, settlement feed).
const date = new Date().toISOString().slice(0, 10);

// System A: canonical events from ingestion
const systemA = [
  { entity_type: 'event', entity_id: 'evt_demo_football_02', data: { status: 'ended', score: { home: 2, away: 1 } }, source_system: 'ingestion' },
  { entity_type: 'event', entity_id: 'evt_demo_basketball_01', data: { status: 'ended', score: { home: 102, away: 98 } }, source_system: 'ingestion' },
  { entity_type: 'settlement', entity_id: 'evt_demo_football_02|match_winner|home', data: { outcome: 'won', confidence: 1.0 }, source_system: 'ingestion' }
];

// System B: settlement feed / provider
const systemB = [
  { entity_type: 'event', entity_id: 'evt_demo_football_02', data: { status: 'ended', score: { home: 2, away: 1 } }, source_system: 'settlement_feed' },
  { entity_type: 'event', entity_id: 'evt_demo_basketball_01', data: { status: 'ended', score: { home: 102, away: 100 } }, source_system: 'settlement_feed' },
  { entity_type: 'settlement', entity_id: 'evt_demo_football_02|match_winner|home', data: { outcome: 'won', confidence: 1.0 }, source_system: 'settlement_feed' }
];

return [{
  json: { date, system_a: systemA, system_b: systemB }
}];

// Compare checksums across systems and detect drift.
// Mirrors processing_engine.reconciliation.drift_detector.DriftDetector.detect
const { system_a, system_b, date } = $json;

function computeChecksum(entityType, entityId, data) {
  const payload = { entity_type: entityType, entity_id: entityId, data };
  const str = JSON.stringify(payload, Object.keys(payload).sort());
  return str.length + ':' + JSON.stringify(payload).slice(0, 12);
}

const indexA = new Map();
const indexB = new Map();
for (const r of system_a) indexA.set(`${r.entity_type}|${r.entity_id}`, r);
for (const r of system_b) indexB.set(`${r.entity_type}|${r.entity_id}`, r);

const discrepancies = [];
const allKeys = new Set([...indexA.keys(), ...indexB.keys()]);
for (const key of allKeys) {
  const [entityType, entityId] = key.split('|');
  const a = indexA.get(key);
  const b = indexB.get(key);
  if (a && b) {
    const ca = computeChecksum(entityType, entityId, a.data);
    const cb = computeChecksum(entityType, entityId, b.data);
    if (ca !== cb) {
      const allFields = new Set([...Object.keys(a.data || {}), ...Object.keys(b.data || {})]);
      for (const f of allFields) {
        if (JSON.stringify(a.data[f]) !== JSON.stringify(b.data[f])) {
          discrepancies.push({
            entity_type: entityType,
            entity_id: entityId,
            field: f,
            expected: a.data[f],
            actual: b.data[f],
            severity: ['outcome','odds','status','score'].includes(f) ? 'high' : 'medium'
          });
        }
      }
    }
  } else if (a && !b) {
    discrepancies.push({ entity_type: entityType, entity_id: entityId, field: '__entity__', expected: 'present', actual: 'missing', severity: 'high' });
  } else if (!a && b) {
    discrepancies.push({ entity_type: entityType, entity_id: entityId, field: '__entity__', expected: 'missing', actual: 'present', severity: 'high' });
  }
}

const matched = system_a.length - discrepancies.length;
return [{
  json: { date, total_events: system_a.length, matched, discrepancies, source_a: 'ingestion', source_b: 'settlement_feed' }
}];

// Auto-correct safe discrepancies and flag the rest.
// Mirrors processing_engine.reconciliation.auto_corrector.AutoCorrector.correct
const { date, total_events, matched, discrepancies } = $json;

const safeFields = new Set(['score', 'status', 'metadata']);
const corrected = [];
const flagged = [];

for (const d of discrepancies) {
  const isFinancial = ['outcome', 'odds', 'selection_id', 'market_id'].includes(d.field);
  const isEntityMissing = d.field === '__entity__';
  if (isFinancial || isEntityMissing || d.severity === 'high') {
    flagged.push({ ...d, corrected: false, reason: 'high severity or financial field; manual review required', corrected_value: d.expected });
  } else if (safeFields.has(d.field) && ['low', 'medium'].includes(d.severity)) {
    corrected.push({ ...d, corrected: true, reason: 'auto-corrected to expected value', corrected_value: d.expected });
  } else {
    flagged.push({ ...d, corrected: false, reason: 'not auto-correctable; manual review required', corrected_value: d.expected });
  }
}

return [{
  json: { date, total_events, matched, discrepancies, corrected, flagged }
}];

// Build the ReconciliationReport for the date
const { date, total_events, matched, discrepancies, corrected, flagged } = $json;
const report = {
  date,
  total_events,
  matched,
  discrepancies,
  auto_corrected: corrected.filter(c => c.corrected).length,
  manual_review_required: flagged.length
};

// Emit critical alert if too many discrepancies (per PROJECT_SPEC: > 100)
const critical = discrepancies.length > 100;

return [{
  json: {
    report,
    critical_alert: critical,
    alert_payload: critical ? {
      anomaly_type: 'reconciliation_drift',
      context: { discrepancy_count: discrepancies.length, date },
      event_data: { id: date }
    } : null
  }
}];
